parameters.jsonBody:
={
  "contents": [{
    "parts": [{
      "text": {{ JSON.stringify(
        "You are classifying a real estate buyer reply to a re-engagement email. Classify their INTENT accurately.\n\n" +
        "REPLY TEXT: " + ($('Extract Reply Context').item.json.reply_text || 'empty') + "\n" +
        "REPLY SUBJECT: " + ($('Extract Reply Context').item.json.reply_subject || 'empty') + "\n" +
        "SENDER EMAIL: " + ($('Extract Reply Context').item.json.from_email || 'unknown') + "\n\n" +
        "Classify into ONE of these intent categories:\n" +
        "- hot: buyer is actively re-engaged wants floor plans budget or a meeting\n" +
        "- warm: buyer acknowledges shows mild interest but no urgency no next step\n" +
        "- not_interested: buyer already purchased no longer looking clearly declines\n" +
        "- unsubscribe: buyer asks to stop being contacted remove me dont email\n" +
        "- unclear: cannot confidently classify\n\n" +
        "Return VALID JSON only with these keys:\n" +
        "- intent: one of the 5 categories above\n" +
        "- confidence: high medium low\n" +
        "- reasoning: one line explaining why\n" +
        "- suggested_rm_action: one line action for the RM (only if intent is hot or warm)\n" +
        "- key_phrase: exact quote from reply that drove the classification\n\n" +
        "Return ONLY the JSON no markdown fences."
      ) }}
    }]
  }],
  "generationConfig": {
    "temperature": 0.2,
    "maxOutputTokens": 512,
    "responseMimeType": "application/json"
  }
}
